import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int M = scanner.nextInt();

        int[] dp_array = new int[n + 1];
        int[] accu_array = new int[n + 1];

        if (n >= 1) {
            dp_array[1] = 1;
            accu_array[1] = 1;
        }
        if (n >= 2) {
            dp_array[2] = 1;
            accu_array[2] = 2;
        }

        for (int i = 3; i <= n; i++) {
            dp_array[i] = accu_array[i - 1];
            int limit = (int) Math.sqrt(i);
            for (int divisor = 1; divisor <= limit; divisor++) {
                if (i % divisor == 0) {
                    dp_array[i] += dp_array[divisor];
                    dp_array[i] %= M;
                    if (divisor > 1 && divisor * divisor < i) {
                        dp_array[i] += dp_array[i / divisor];
                        dp_array[i] %= M;
                    }
                }
            }
            accu_array[i] = (accu_array[i - 1] + dp_array[i]) % M;
        }

        System.out.println(accu_array[n]);
        scanner.close();
    }
}
